INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Kajal Aggarwal', 'kajal-aggarwal', 'Kajal Aggarwal is an immensely popular, charismatic, and celebrated Indian actress who has established herself as one of the leading female superstars of South Indian cinema across an illustrious career spanning two decades in Telugu, Tamil, and Hindi film industries. Born in 1985 in Mumbai, Maharashtra, into a Punjabi family, Aggarwal earned a degree in Mass Media with a specialization in marketing and advertising before pursuing her passion for performance. She made her acting debut in the Hindi film Kyun! Ho Gaya Na... (2004) before transitioning to Telugu cinema with Teja\'s Lakshmi Kalyanam (2007). Her meteoric rise to super-stardom arrived in 2009 with S. S. Rajamouli\'s historical fantasy magnum opus Magadheera, where her dual portrayal of the dignified 17th-century royal princess Mithravinda Devi and the modern, vivacious Indu opposite Ram Charan garnered universal acclaim, won her a Filmfare Award nomination for Best Actress, and permanently cemented her as a top-tier leading lady. Over the ensuing years, Aggarwal delivered a string of monumental commercial blockbusters, including Darling (2010), Brindavanam (2010), Mr. Perfect (2011), Businessman (2012), and the Tamil blockbuster Thuppakki (2012) opposite Vijay. She also made a prominent mark in Hindi cinema opposite Ajay Devgn in the box-office smash Singham (2011) and Special 26 (2013). Known for her radiant screen presence, emotive eyes, and versatility in effortlessly balancing light-hearted romantic comedies with intense dramatic roles, Aggarwal became the first South Indian actress to have a wax statue immortalized at Madame Tussauds Singapore.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Kichcha Sudeepa', 'kichcha-sudeepa', 'Sudeepa Sanjeev, universally celebrated by his mononym Kichcha Sudeepa, is a towering, multi-faceted superstar of Kannada and Indian cinema whose intense screen presence, resonant baritone, and ferocious acting caliber have earned him widespread critical adulation and commercial supremacy across multiple languages. Born in 1973 in Shimoga, Karnataka, Sudeepa completed a bachelor\'s degree in mechanical engineering before enrolling at the Roshan Taneja School of Acting in Mumbai to master the dramatic arts. His career erupted into phenomenal acclaim with the 2003 Kannada romantic tragedy Huchcha, where his electrifying portrayal of the tragic lover Kichcha struck a deep chord with audiences and earned him the enduring moniker \'Kichcha Sudeepa\'. He went on to star in and direct celebrated Kannada blockbusters such as My Autograph (2006), No 73, Shanthi Nivasa (2007), Veera Madakari (2009), and Kempe Gowda (2011). His national and international breakthrough came under S. S. Rajamouli\'s visionary direction in Eega (2012), where his bravura, vanity-fueled performance as the villainous tycoon Sudeep battling a reincarnated fly captivated audiences worldwide, winning him the Filmfare Award for Best Supporting Actor – Telugu. He continued his pan-Indian expansion with menacing turns in Salman Khan\'s Dabangg 3 (2019) and the adventure epic Vikrant Rona (2022). In addition to his prolific acting and directing career, Sudeepa is a passionate cricket enthusiast who captains the Karnataka Bulldozers in the Celebrity Cricket League and has hosted Bigg Boss Kannada for over a decade with unmatched charisma.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Shriya Saran', 'shriya-saran', 'Shriya Saran is an accomplished, graceful, and internationally recognized Indian actress and classical dancer whose vibrant career across South Indian, Hindi, and American cinema has made her one of the most beloved and enduring leading ladies of modern Indian films. Born in 1982 in Dehradun, Uttarakhand, Saran trained extensively from childhood in Kathak and Rajasthani folk dance under the tutelage of Shovana Narayan, developing an innate physical poise, expressiveness, and artistic discipline that naturally translated onto the silver screen. She was discovered in a music video while studying at Lady Shri Ram College in Delhi and made her film debut in the Telugu drama Ishtam (2001). Her breakthrough commercial triumph came opposite Nagarjuna in Santosham (2002), followed by a string of high-profile successes including Tagore (2003) opposite Chiranjeevi and S. S. Rajamouli\'s action blockbuster Chatrapathi (2005) opposite Prabhas, where her charming portrayal of Neelu added romantic warmth to the gritty narrative. In 2007, she scaled the absolute summit of Indian box office glory by starring as the female lead alongside superstar Rajinikanth in S. Shankar\'s Tamil magnum opus Sivaji: The Boss, which became the highest-grossing Tamil film of its time. Saran also ventured into Hollywood with The Other End of the Line (2008) and Deepa Mehta\'s adaptation of Salman Rushdie\'s Midnight\'s Children (2012). Her remarkable dramatic depth was further showcased in the universally acclaimed Drishyam franchise (2015 and 2022) as Nandini Salgaonkar opposite Ajay Devgn.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Ravi Teja', 'ravi-teja', 'Bhupatiraju Ravi Shankar Raju, known universally by his screen name Ravi Teja and affectionately crowned \'Mass Maharaja\' by millions of fans, is one of the most energetic, beloved, and self-made superstars in the history of Telugu cinema. Born in 1968 in Jaggampeta, Andhra Pradesh, Teja spent his formative years in Jaipur, Delhi, and Vijayawada before heading to Chennai with zero film background, determined to make it in the movies. He spent nearly a decade grinding through uncredited roles, working as an assistant director, and playing minor character parts before his raw, kinetic charisma broke through in Krishna Vamsi\'s Sindhooram (1997). His breakthrough as a lead hero arrived with Puri Jagannadh\'s Itlu Sravani Subramanyam (2001) and the sensational industry hit Idiot (2002), which established his trademark irreverent body language, blistering dialogue delivery, and relatable working-class swagger. In 2006, Teja delivered what is widely considered his career-defining masterpiece in S. S. Rajamouli\'s Vikramarkudu, demonstrating breathtaking dramatic duality as the hilarious, lovable thief Athili Sathi Babu and the ferocious, terrifyingly resolute police officer ASP Vikram Singh Rathore. The performance cemented his status as an A-list titan. Over a glorious career, he has headlined iconic blockbusters including Kick (2009), Mirapakay (2011), Balupu (2013), Raja the Great (2017), Krack (2021), and Dhamaka (2022). His relentless infectious energy, comic timing, and refusal to surrender inspire aspiring outsiders across the country.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Anushka Shetty', 'anushka-shetty', 'Sweety Shetty, known professionally by her screen name Anushka Shetty and revered as the undisputed \'Lady Superstar\' of South Indian cinema, is a majestic, versatile, and commanding actress whose monumental performances have reshaped female-led commercial cinema across Telugu and Tamil industries. Born in 1981 in Mangalore, Karnataka, into a Tulu-speaking Bunt family, Shetty graduated with a degree in Computer Applications from Mount Carmel College, Bangalore, and was a certified yoga instructor under Bharat Thakur before stepping into films. She made her debut in Puri Jagannadh\'s Super (2005) opposite Nagarjuna, but her meteoric commercial ascendancy was ignited in 2006 when S. S. Rajamouli cast her as the vivacious rural beauty Neeraja in the blockbuster Vikramarkudu. Shetty dismantled gender barriers in Indian commercial cinema with the 2009 dark fantasy horror epic Arundhati, where her fierce, authoritative performance as a valiant queen battling an evil sorcerer shattered box office records, won her the Filmfare Award for Best Actress, and proved a woman could anchor an industry blockbuster. She reunited with S. S. Rajamouli for the globally historic Baahubali franchise (2015 and 2017) as Devasena, whose unyielding pride, fiery defiance against tyranny, and majestic royal poise became one of Indian cinema\'s most iconic feminist characters. Her diverse filmography also features the critically adored Rudhramadevi (2015), Vedam (2010), and the Singam franchise opposite Suriya. Her commanding screen aura and emotional gravity place her among the all-time greats of Indian film.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Jr. NTR', 'n-t-rama-rao-jr', 'Nandamuri Taraka Rama Rao Jr., widely celebrated as Jr. NTR or \'Man of Masses\', is a titan of contemporary Indian cinema whose incandescent screen presence, thunderous dialogue delivery, peerless classical Kuchipudi dance virtuosity, and emotional ferocity have made him a global icon. Born in 1983 in Hyderabad into Telugu cinema\'s most revered royal dynasty as the grandson of the legendary N. T. Rama Rao, he debuted as a child artist in Ramayanam (1996), winning the National Film Award for Best Children\'s Film. His adult career ignited under S. S. Rajamouli\'s direction with Student No. 1 (2001) and exploded into historic phenomenon with Simhadri (2003), where at just 20 years old, his electrifying mass performance shattered all box office records. He continued to break ground in Rajamouli\'s Yamadonga (2007) and delivered critically celebrated blockbusters including Aadi (2002), Adhurs (2010), Temper (2015), Nannaku Prematho (2016), and Janatha Garage (2016). In 2022, his collaborative journey with Rajamouli reached the international pinnacle with the Oscar-winning global phenomenon RRR, where his breathtaking, soul-stirring portrayal of tribal revolutionary Komaram Bheem — alongside his viral, gravity-defying performance in the Academy Award-winning song \'Naatu Naatu\' — earned universal acclaim from Hollywood and international film critics alike. Celebrated for his ability to convey explosive volcanic rage and tender vulnerability in the same breath, Jr. NTR stands as one of Indian cinema\'s most complete and gifted actors.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Sunil', 'sunil', 'Sunil Varma, known mononymously as Sunil, is a remarkably versatile, beloved, and multi-award-winning Indian actor, comedian, and dancer who carved an indelible legacy in Telugu cinema through his peerless slapstick timing, relatable physical comedy, and later reinvented himself as both a successful lead hero and a menacing villain. Born in 1974 in Bhimavaram, Andhra Pradesh, Sunil faced immense early hardship, losing his father at age five and enduring years of poverty and rejection in Hyderabad while pursuing a film career alongside his close friend, writer-director Trivikram Srinivas. His career skyrocketed with sensational comedic breakthroughs in Nuvve Kavali (2000), Nuvvu Nenu (2001), Manasantha Nuvve (2001), and Trivikram\'s Nuvvu Naaku Nachav (2001), where his idiosyncratic dialect, expressive face, and astonishing dancing ability made him an indispensable fixture of early 2000s Telugu cinema, winning three Filmfare Awards and multiple Nandi Awards. In 2010, S. S. Rajamouli placed immense trust in him by casting him as the lead protagonist in Maryada Ramanna, where Sunil\'s earnest, vulnerable, and hilarious portrayal of the trapped innocent Ramu propelled the film to monumental commercial success. After headlining hit comedies like Poola Rangadu (2012), Sunil underwent a stunning dramatic metamorphosis into a chilling antagonist in Allu Arjun\'s Pushpa: The Rise (2021) as Mangalam Srinu and Nelson\'s Jailer (2023) opposite Rajinikanth, proving his extraordinary artistic range.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Nithiin', 'nithiin', 'Nithiin Kumar Reddy, known professionally by his mononym Nithiin, is a dynamic, stylish, and highly successful Indian actor and producer in Telugu cinema who has maintained an enduring, two-decade career through his youthful screen charisma, effortless comedic flair, and passionate dedication to romantic-action cinema. Born in 1983 in Nizamabad, Telangana, into a film distribution family, Nithiin was inspired by Pawan Kalyan and entered the film industry at the age of nineteen, making an explosive debut in Teja\'s romantic drama Jayam (2002), which became an industry blockbuster and earned him the Filmfare Award for Best Male Debut – South. In 2004, he collaborated with S. S. Rajamouli in the groundbreaking sports-action film Sye, where his intensely athletic, emotionally charged portrayal of student leader Prudhvi leading a college rugby squad against a mafia cartel established him as a versatile action hero capable of commanding physical roles. Following a challenging career phase, Nithiin orchestrated one of Telugu cinema\'s most celebrated box office comebacks with Vikram Kumar\'s poetic romance Ishq (2012) and Gunde Jaari Gallanthayyinde (2013). He solidified his A-list standing under Trivikram Srinivas\'s direction in the family entertainer A Aa (2016) opposite Samantha, and delivered subsequent successes with Bheeshma (2020) and Macherla Niyojakavargam (2022). In addition to acting, Nithiin is a successful producer heading Sreshth Movies, continually backing innovative, youth-oriented cinematic ventures.', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();
INSERT INTO `people` (`name`, `slug`, `biography`, `known_for_department`, `gender`, `created_at`, `updated_at`)
VALUES ('Genelia D\'Souza', 'genelia-dsouza', 'Genelia D\'Souza is a delightfully exuberant, naturally spontaneous, and universally cherished Indian actress and producer whose effervescent charm, expressive eyes, and infectious screen vitality made her the definitive girl-next-door of 2000s Indian cinema across Telugu, Tamil, and Hindi industries. Born in 1987 in Mumbai, Maharashtra, into a Mangalorean Catholic family, D\'Souza was a state-level athlete and national-level football player before catching the attention of filmmaker Shankar through a memorable Parker Pen television commercial opposite Amitabh Bachchan. She made an unprecedented triple debut in 2003, starring in Tujhe Meri Kasam (Hindi), Shankar\'s Boys (Tamil), and Satyam (Telugu). In 2004, she teamed up with S. S. Rajamouli in the sports-action hit Sye as the vivacious Indu, winning over college audiences with her sparkling screen presence. Her career reached astronomical, historic heights in 2006 with Bhaskar\'s Telugu cult romance Bommarillu, where her portrayal of the innocent, eccentric, and lovable Hasini won her the Filmfare Award for Best Actress – Telugu and became one of the most culturally iconic female characters in South Indian film history. She replicated that magical charm in Bollywood with the massive romantic hit Jaane Tu... Ya Jaane Na (2008) as Aditi opposite Imran Khan. Later turning producer alongside her husband Riteish Deshmukh, she produced and starred in the critically acclaimed and commercially historic Marathi blockbuster Ved (2022).', 'Acting', 'not_specified', NOW(), NOW())
ON DUPLICATE KEY UPDATE `biography` = VALUES(`biography`), `updated_at` = NOW();

