-- Title: Magadheera
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Magadheera', 'magadheera-2009', 'A love that survived 400 years.', 'Magadheera is a visually lavish, emotionally soaring, and genre-defining reincarnation fantasy blockbuster directed by S. S. Rajamouli, which transformed Telugu cinema, set unprecedented industry box office records, and proved that Indian mythic spectacle could match global cinema in scale, kinetic visual effects, and grand emotional catharsis. The narrative begins in modern-day Hyderabad, where Harsha, an adrenaline-fueled motorcycle racer with a carefree streak, accidentally touches the fingertips of a young woman named Indu at an auto stand. The momentary physical contact triggers an overwhelming, unexplained sensory surge of past-life memories and electric familiarity. As Harsha desperately tries to track down Indu, unaware that she is a wealthy heiress, an ominous and wealthy suitor named Raghuveer enters her life. Raghuveer is secretly consumed by a murderous lust and past-life vendetta against Harsha. When Raghuveer frames Harsha for the murder of Indu\'s father and kidnaps her, Harsha is plunged into a lake, which awakens his complete memories of their previous birth four hundred years earlier in the 17th-century kingdom of Udayghad. In that life, Harsha was Kala Bhairava, the peerless royal warrior of the Senapati clan, fiercely devoted to Princess Mithravinda, whose heart he won through chivalry and valor. However, the treacherous cousin Ranadev Billa (reborn as Raghuveer) aligned with invading Mughal general Sher Khan to seize the throne and force Mithravinda into marriage, culminating in Kala Bhairava\'s legendary last stand atop the Bhairavakona cliff where he single-handedly slaughtered one hundred enemy soldiers before falling to his death trying to save the princess. Reborn in modern times, Harsha must awaken his ancient warrior spirit to avenge his past and reclaim his eternal love.', 'titles/posters/ssr_magadheera_2009.jpg', '2009-07-31', 166, 'U/A', 7.8, 350000000, 1500000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 1, `id` FROM `titles` WHERE `slug` = 'magadheera-2009';
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 9, `id` FROM `titles` WHERE `slug` = 'magadheera-2009';
INSERT IGNORE INTO `genre_title` (`genre_id`, `title_id`) SELECT 7, `id` FROM `titles` WHERE `slug` = 'magadheera-2009';
