-- Title: Eega
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Eega', 'eega-2012', 'Revenge has a new shape.', 'Eega (released in Hindi as Makkhi) is an astonishingly inventive, globally acclaimed, and delightfully audacious fantasy revenge thriller directed by S. S. Rajamouli, widely celebrated as one of the most uniquely creative achievements in the history of commercial Indian cinema. The heartwarming first act follows Nani, a cheerful, hardworking graphic designer who has spent two years patiently and playfully wooing Bindu, a gentle micro-artist and NGO worker who secretly reciprocates his deep affection but loves keeping him guessing. Their blossoming romance is abruptly shattered by Sudeep, an immensely wealthy, narcissistic, and predatory industrialist who is accustomed to possessing any woman he desires. When Sudeep sets his sights on Bindu and realizes she loves Nani instead of him, his psychopathic vanity curdles into murderous rage. Sudeep kidnaps Nani, brutally tortures him, and hangs him in an abandoned warehouse, staging the murder as a suicide just as Bindu is preparing to confess her love. In his dying breath, Nani vows vengeance. In an unprecedented narrative leap, Nani is reincarnated as a common housefly — an eega — endowed with human memories, consciousness, and an unquenchable thirst for retribution. Realizing his microscopic physical vulnerability, the fly uses razor-sharp intellect, tactical sabotage, and psychological warfare to make Sudeep\'s life a living nightmare: causing catastrophic car accidents, triggering insomnia, ruining multimillion-dollar business deals, and tattooing warnings in spilled tea. When Sudeep discovers the fly is Nani\'s spirit, he deploys flamethrowers, bodyguards, and occultists, culminating in an electrifying, emotional showdown where the tiny insect arms himself with miniature needles to protect Bindu and destroy his killer.', 'titles/posters/ssr_eega_2012.jpg', '2012-07-06', 145, 'U/A', 7.7, 300000000, 1300000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
