-- Title: Chatrapathi
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Chatrapathi', 'chatrapathi-2005', 'A leader born from the tears of the oppressed.', 'Chatrapathi is an intense, emotionally volcanic, and profoundly moving action drama directed by S. S. Rajamouli, marking his first historic collaboration with superstar Prabhas and establishing the director-actor partnership that would eventually conquer Indian cinema with the Baahubali franchise. The film opens in a coastal village in Sri Lanka, where Sivaji, an orphaned boy, is adopted and showered with maternal love by a kind-hearted woman named Parvati, much to the bitter, festering resentment of her biological son Ashok. When ethnic riots erupt in Sri Lanka, the refugees are forcibly evacuated to India on overcrowded boats. During the harrowing escape, Ashok maliciously deceives his mother into believing Sivaji drowned at sea, cruelly severing mother and son. Reaching the port city of Visakhapatnam, Sivaji and fellow refugees are enslaved by local port mafioso Baji Rao and his sadistic younger brother Ras Bihari, who exploit the undocumented migrants as bonded laborers under subhuman conditions. For twelve years, Sivaji endures the torment while tirelessly searching for his lost mother. However, when Ras Bihari\'s goons kill an innocent refugee child and demand obedience, Sivaji\'s patience turns into raw, unstoppable fury. In an iconic, rain-soaked confrontation, Sivaji single-handedly decapitates the tyrant, liberating the entire coastal colony. The oppressed refugees hail him as their supreme savior and christen him \'Chatrapathi\' — a warrior king defending the helpless. But as Sivaji wages war against international smuggler Katraju, his treacherous stepbrother Ashok resurfaces, threatening to destroy Sivaji\'s empire and poison his long-sought reunion with his beloved mother.', 'titles/posters/ssr_chatrapathi_2005.jpg', '2005-09-29', 158, 'A', 7.7, 80000000, 220000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
