-- Title: Vikramarkudu
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Vikramarkudu', 'vikramarkudu-2006', 'Jintatha Chitha Chitha… the lion has awakened.', 'Vikramarkudu is an electrifying, furiously entertaining, and massively influential action masala masterpiece directed by S. S. Rajamouli, showcasing \'Mass Maharaja\' Ravi Teja in a legendary dual performance that redefined heroic archetypes and became a nationwide sensation, spawning blockbuster remakes in Hindi (Rowdy Rathore starring Akshay Kumar), Tamil (Siruthai starring Karthi), Kannada (Veera Madakari), and Bengali. The narrative opens in Hyderabad with Athili Sathi Babu, a clever, street-smart petty thief and con man who, alongside his loyal sidekick Duvva Abbulu, pulls off humorous heists while falling head over heels for a spirited rural girl named Neeraja. Sathi Babu\'s carefree life is upended when a mysterious trunk he steals reveals not gold or jewels, but a terrified little girl named Neha who clings to him, tearfully calling him \'Daddy\'. Convinced he has been framed, Sathi Babu tries desperately to abandon her, but finds his conscience stirred as brutal, machete-wielding assassins descend upon them from the lawless badlands of Chambal. When Sathi Babu is ambushed and on the verge of death, the mysterious assassins are wiped out by a terrifyingly identical figure: Assistant Superintendent of Police Vikram Singh Rathore. The mortally wounded police officer\'s backstory is revealed: a fearless, unbribable cop who single-handedly waged war against the barbaric feudal despot Bavuji and his depraved son Munna in the terrorized village of Devgarh. Before succumbing to bullet wounds, Rathore entrusts his daughter to Sathi Babu. Deeply moved and transformed by the noble sacrifice, the petty con man assumes the identity of Vikram Rathore, strapping on the khaki uniform to unleash absolute, ruthless vengeance on Bavuji\'s criminal empire.', 'titles/posters/ssr_vikramarkudu_2006.jpg', '2006-06-23', 140, 'A', 7.7, 110000000, 250000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
