-- Title: Simhadri
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Simhadri', 'simhadri-2003', 'A gentle servant… a ruthless storm.', 'Simhadri is an industry-shaking, earth-shattering action blockbuster directed by S. S. Rajamouli, which transformed a 20-year-old Jr. NTR into an undisputed mass demigod, rewrote Telugu cinema box office records, and established Rajamouli as the most formidable commercial filmmaker of his generation. The story centers on Simhadri, a remarkably humble, devoted, and warm-hearted servant raised from childhood in the aristocratic household of Ram Bhupal Varma in Visakhapatnam. Loved like a son by Varma and adored as a selfless guardian angel by the local townspeople, Simhadri is the epitome of non-violence and filial loyalty. However, his placid life becomes complicated when he encounters Indu, an intellectually disabled, amnesiac orphan girl whose childlike innocence awakens a fierce, protective paternal instinct within him. Despite facing societal outrage, family accusations of betrayal, and romantic complications with Varma\'s granddaughter Kasturi, Simhadri secretly arranges for Indu to undergo high-risk neurosurgery in Kerala. When the operation succeeds and Indu regains her memory, she attempts to murder Simhadri, shocking everyone. This unmasks Simhadri\'s terrifying secret past: two years earlier, he was \'Simhadri Annan\', a lethal underworld warlord in the heart of Trivandrum, Kerala, who took up weapons to avenge the gruesome massacre of Indu\'s family by the ruthless international mafia kingpin Bhai Saab. Having sworn an oath to the dying family to keep Indu alive at all costs, Simhadri had embraced exile and assumed a docile servant\'s life. With Bhai Saab discovering Indu\'s survival, the docile servant must re-awaken his devastating warrior persona to wage an apocalyptic final war.', 'titles/posters/ssr_simhadri_2003.jpg', '2003-07-09', 165, 'A', 7.4, 85000000, 260000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
