-- Title: Yamadonga
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Yamadonga', 'yamadonga-2007', 'A thief so clever, he can outwit the God of Death.', 'Yamadonga is a lavish, brilliantly inventive, and wildly entertaining socio-fantasy action comedy directed by S. S. Rajamouli, celebrating classical mythological Telugu cinema through cutting-edge visual effects, razor-sharp dialogue, and an extraordinary central clash of acting titans between Jr. NTR and veteran legend Mohan Babu. The story revolves around Raja, an irreverent, sharp-witted, and utterly shameless orphan thief in Hyderabad who will do anything for quick cash, constantly accompanied by his exasperated sidekick Satti. Raja discovers that Mahi, a wealthy, soft-hearted heiress whom he had saved as a young girl, has waited for him all her life, believing him to be her destined protector. However, Mahi\'s cruel and greedy relatives are scheming to assassinate her to seize her immense inheritance. Greedy for her wealth, Raja initially pretends to reciprocate her devotion, but when Mahi\'s treacherous relatives hire contract killers to eliminate him, Raja is unexpectedly murdered and his soul is dragged down into Yamaloka — the Hindu Netherworld — by the Yamadutas. Arriving in the grand golden court of Lord Yama, the righteous God of Death, Raja refuses to accept his death, arguing that his lifespan was cut short by treachery. Using his silver tongue, audacious theatricality, and incisive legal arguments, Raja sows total chaos across the celestial realm: unionizing the tortured souls of Naraka into a labor strike against Yama, wooing celestial apsaras, and stealing Lord Yama\'s omnipotent Yamapasam (the sacred noose). Through a hilarious, mythic power play, Raja temporarily dethrones Yama and assumes the throne of Death himself before returning to the mortal realm to protect Mahi and crush her wicked family.', 'titles/posters/ssr_yamadonga_2007.jpg', '2007-08-15', 174, 'U/A', 7.2, 140000000, 300000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
