-- Title: Maryada Ramanna
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Maryada Ramanna', 'maryada-ramanna-2010', 'Hospitality is God… until you step outside.', 'Maryada Ramanna is a masterclass in high-concept comedic suspense and clockwork narrative tension directed by S. S. Rajamouli, which proved that the visionary filmmaker could deliver an industry-wide blockbuster without massive star power or colossal battle sequences, relying purely on impeccable writing, situational irony, and edge-of-the-seat storytelling (later remade into the Hindi box-office hit Son of Sardaar starring Ajay Devgn). The premise is rooted in the fierce, blood-soaked faction feud culture of Rayalaseema, where an ancient tribal code dictates that even your worst mortal enemy cannot be harmed while they are a guest inside your home. The protagonist is Kovelamudi Ramu, a gentle, painfully naive, and impoverished young man struggling to make ends meet in Hyderabad with his loyal bicycle. Ramu discovers that he has inherited five acres of ancestral land in a distant Rayalaseema village and travels there on a train, striking up a warm, charming friendship with a spirited co-passenger named Aparna. Upon reaching the village, Ramu is hospitably welcomed into the palatial mansion of Ramineedu, a fearsome factionist patriarch and Aparna\'s father. While enjoying the family\'s lavish feast, Ramu is horrified to discover that Ramineedu\'s brother was killed twenty-eight years ago by Ramu\'s father, and Ramineedu and his bloodthirsty sons have sworn a blood oath to butcher the killer\'s heir on sight. However, because Ramu entered as a guest, the code of hospitality forbids them from killing him indoors. What ensues is an exquisitely tortuous, hilarious psychological thriller as Ramu invents absurd excuses to remain permanently trapped inside the house, while the family waits with gleaming axes just outside the front door.', 'titles/posters/ssr_maryada_ramanna_2010.JPG', '2010-07-23', 137, 'U', 7.4, 120000000, 300000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
