-- Title: Sye
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Sye', 'sye-2004', 'A clash of egos… a battle for survival.', 'Sye is a pioneering, high-voltage, and trendsetting sports-action college drama directed by S. S. Rajamouli, which introduced the brutal, adrenaline-charged sport of Rugby to mainstream Indian audiences and proved Rajamouli\'s singular ability to fuse visceral Western sporting intensity with unabashed Indian emotional drama and commercial heroics. The story is set at an elite Hyderabad college where campus life is dominated by the bitter, violent feud between two student factions: the arts and commerce students led by the charismatic, street-smart Prudhvi, and the science students led by the suave, fiercely competitive Shashank. Their petty tribal rivalry spills into bloody hallway brawls, student elections, and pranks, with both factions competing for the attention of a vivacious fellow student named Venu. However, their college bubble is violently shattered when Bikshu Yadav, a ruthless, bloodthirsty mafia don who operates with complete political impunity, targets their university\'s prime multi-acre real estate. Through forged documents and corrupt municipal officials, Bikshu Yadav illegally seizes the college campus, evicting the students, brutally thrashing the faculty, and turning the grounds into a criminal headquarters. Devastated and rendered powerless against political muscle and guns, Prudhvi and Shashank realize that their internal hatred has made them easy prey. When Bikshu Yadav mockingly agrees to a bet — that the students can reclaim their college if they can defeat his brutal, professional private rugby team in a full-contact match — the two warring student factions must bury their egos and forge an unbreakable brotherhood on the muddy pitch in a grueling, bloody athletic war for their dignity and future.', 'titles/posters/ssr_sye_2004.jpg', '2004-07-01', 148, 'A', 7.2, 60000000, 160000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
