-- Title: Student No. 1
INSERT INTO `titles` (`title`, `slug`, `tagline`, `overview`, `poster_path`, `release_date`, `runtime_minutes`, `content_rating`, `rating`, `budget`, `box_office`, `original_language`, `type`, `status`, `created_at`, `updated_at`)
VALUES ('Student No. 1', 'student-no-1-2001', 'A student by day… a convict by night.', 'Student No. 1 is the electrifying, heartwarming, and historically momentous directorial debut of S. S. Rajamouli, which launched one of the greatest director-star partnerships in Indian cinema history alongside an 18-year-old Jr. NTR, establishing the filmmaker\'s innate mastery over emotional manipulation, high-stakes moral dilemmas, and explosive mass elevation. The story begins at an esteemed law college in Visakhapatnam, where Aditya, a polite, extraordinarily disciplined, and deeply studious young man, enrolls as a freshman. Unlike his rowdy, undisciplined peers, Aditya avoids all confrontations, submits his assignments with religious diligence, and maintains a strictly regimented schedule, earning the admiration of his professors and the romantic fascination of an outspoken classmate named Anjali. However, Aditya\'s studious demeanor conceals a startling, disquieting reality: every evening at precisely seven o\'clock, he is escorted back to the central prison, returning to his cold cell as convict prisoner number 409 under a special daytime educational parole scheme. As campus bullies and corrupt politicians attempt to drag Aditya into violent street clashes, his past is unraveled through a heartbreaking flashback: raised by an upright, proud father who dreamed of his son becoming an advocate for justice, Aditya was framed for a horrific crime of passion and sentenced to life imprisonment after accidentally killing a brutal criminal to protect a woman\'s honor. With his grief-stricken father disowning him in disgust, Aditya\'s only purpose in studying law is to present his own appeal in the High Court, prove his moral innocence to his father, and restore his family\'s lost honor.', 'titles/posters/ssr_student_no_1_2001.jpg', '2001-09-27', 150, 'U', 7, 25000000, 120000000, 'Telugu', 'movie', 'released', NOW(), NOW())
ON DUPLICATE KEY UPDATE `overview` = VALUES(`overview`), `tagline` = VALUES(`tagline`), `poster_path` = IF(VALUES(`poster_path`) != '', VALUES(`poster_path`), `poster_path`), `updated_at` = NOW();
